 // ResolveLatestCheckpointFromMap picks the checkpoint with the latest CreatedAt
 // from a list of checkpoint IDs. Filters to IDs present in infoMap, then picks
 // the one with the most recent CreatedAt.
 func ResolveLatestCheckpointFromMap(cpIDs []id.CheckpointID, infoMap map[id.CheckpointID]CheckpointInfo) (CheckpointInfo, bool) {
 	var found bool
 	var latest CheckpointInfo
 	for _, cpID := range cpIDs {
 		info, ok := infoMap[cpID]
 		if !ok {
 			continue
 		}
 		if !found || info.CreatedAt.After(latest.CreatedAt) {
 			latest = info
 			found = true
 		}
 	}
 	return latest, found
 }

+// ResolveCheckpointForRewindFromMap picks the checkpoint that should back a
+// logs-only rewind point for a commit containing one or more checkpoint trailers.
+//
+// Rewind semantics follow trailer order, not metadata CreatedAt: the last
+// Entire-Checkpoint trailer in the commit message represents the latest checkpoint
+// for that commit context. If none of the trailer IDs exist in infoMap, returns false.
+func ResolveCheckpointForRewindFromMap(cpIDs []id.CheckpointID, infoMap map[id.CheckpointID]CheckpointInfo) (CheckpointInfo, bool) {
+	for i := len(cpIDs) - 1; i >= 0; i-- {
+		cpID := cpIDs[i]
+		if info, ok := infoMap[cpID]; ok {
+			return info, true
+		}
+	}
+
+	return CheckpointInfo{}, false
+}
